INSERT IGNORE INTO `llm_prompt_template` (`id`, `scene_code`, `scene_name`, `system_prompt`, `user_prompt_tpl`, `output_schema`, `version`, `enabled`, `create_time`, `update_time`) VALUES (1,'alert_explain','告警解读','你是资深SRE。基于告警信息和指标摘要，用简洁中文解释告警。严格输出JSON。','【告警】标题：${title} / 级别：${level} / 对象：${targetName}(${ip})\n指标：${metricName} / 触发值：${triggerValue} / 阈值：${threshold}\n首次触发：${firstTime} / 持续：${duration}分钟 / 累计${count}次\n【指标摘要】当前：${current} 均值：${avg} 峰值：${max} 基线：[${lower},${upper}]\n趋势：${trend} 突变点：${changePoint}\n【历史同期】昨日同时段：${yesterdayAvg} 上周同日：${lastWeekAvg}\n【相关日志摘要】${logTemplateSummary}\n\n输出JSON：\n{\"summary\":\"一句话说明发生了什么（30字内）\",\"severityAssessment\":\"高/中/低\",\"possibleCauses\":[\"...\"],\"logEvidence\":\"日志中支持该判断的证据（若无则说明）\",\"impact\":\"可能影响的业务范围\",\"suggestions\":[\"...\"],\"needImmediateAction\":true,\"confidence\":0.8}','{\"type\": \"object\", \"required\": [\"explanation\", \"possibleCause\", \"suggestion\", \"severity\"], \"properties\": {\"severity\": {\"enum\": [\"low\", \"medium\", \"high\", \"critical\"]}, \"confidence\": {\"type\": \"number\", \"maximum\": 1, \"minimum\": 0}, \"suggestion\": {\"type\": \"string\"}, \"explanation\": {\"type\": \"string\", \"minLength\": 10}, \"possibleCause\": {\"type\": \"string\"}}, \"additionalProperties\": true}',1,1,'2026-09-28 12:00:28','2026-09-30 15:34:51');
INSERT IGNORE INTO `llm_prompt_template` (`id`, `scene_code`, `scene_name`, `system_prompt`, `user_prompt_tpl`, `output_schema`, `version`, `enabled`, `create_time`, `update_time`) VALUES (2,'nl2query','监控问答NL2Query','你是数据查询助手，将自然语言转为结构化查询。可用指标：${metricList} 可用对象：${targetList}。严格输出JSON。','问题：${question}\n输出JSON：\n{\"queryType\":\"metric_query|alert_query|incident_query|unknown\",\"metricKeys\":[\"cpu.usage\"],\"targetIds\":[1],\"startTime\":\"2026-09-27T15:00:00\",\"endTime\":\"2026-09-27T16:00:00\",\"aggregation\":\"avg\",\"step\":\"1m\",\"orderBy\":\"desc\",\"limit\":10,\"explain\":\"查询意图说明\"}\n规则：只能用上述指标与对象，不得编造；无法理解则 queryType=unknown。','{\"type\": \"object\", \"required\": [\"queryType\"], \"properties\": {\"filters\": {\"type\": \"object\"}, \"queryType\": {\"enum\": [\"metric_query\", \"alert_query\", \"incident_query\", \"unknown\"]}, \"targetIds\": {\"type\": \"array\"}, \"timeRange\": {\"type\": \"object\"}, \"metricKeys\": {\"type\": \"array\"}}, \"additionalProperties\": true}',1,1,'2026-09-28 12:00:28','2026-09-30 17:38:33');
INSERT IGNORE INTO `llm_prompt_template` (`id`, `scene_code`, `scene_name`, `system_prompt`, `user_prompt_tpl`, `output_schema`, `version`, `enabled`, `create_time`, `update_time`) VALUES (3,'root_cause','根因分析','你是资深SRE，擅长故障根因分析。给出按可能性排序的根因假设。分析原则：1.优先最早出现异常的组件（时间优先）2.优先拓扑层级更深的组件 3.优先近期有变更的组件 4.必须引用具体指标或日志作为证据，不得凭空推断。严格输出JSON。','【故障事件】标题：${title} 级别：${level} 开始：${startTime} 聚合告警数：${alertCount}\n【并发告警】（按时间排序，格式：[时间] 对象|指标|触发值|描述）\n${alertList}\n【拓扑关系】${faultTarget} ├─宿主：${hostInfo} └─依赖：${dependencies}\n【指标摘要】${metricsSummary}\n【★日志证据】${logTemplateSummary}\n【★日志证据】(近期变更 / 未接入日志)\n【近期变更】${recentChanges}\n\n\n输出JSON：\n{\"primaryCause\":{\"target\":\"\",\"metric\":\"\",\"reason\":\"\",\"confidence\":0.8,\"evidence\":[\"证据1（须引用具体数据或日志）\"]},\"otherCandidates\":[{\"target\":\"\",\"metric\":\"\",\"reason\":\"\",\"confidence\":0.5}],\"reasoningChain\":\"推理链条\",\"logEvidenceUsed\":true,\"suggestions\":[\"...\"],\"needMoreInfo\":[\"...\"],\"similarCaseReference\":{\"caseId\":1,\"howSimilar\":\"...\"}}','{\"type\": \"object\", \"required\": [\"rootCauses\", \"timeline\"], \"properties\": {\"timeline\": {\"type\": \"array\"}, \"confidence\": {\"type\": \"number\", \"maximum\": 1, \"minimum\": 0}, \"rootCauses\": {\"type\": \"array\", \"minItems\": 1}}, \"additionalProperties\": true}',1,1,'2026-09-28 12:00:28','2026-10-02 17:30:39');
INSERT IGNORE INTO `llm_prompt_template` (`id`, `scene_code`, `scene_name`, `system_prompt`, `user_prompt_tpl`, `output_schema`, `version`, `enabled`, `create_time`, `update_time`) VALUES (4,'log_explain','日志解读','你是资深SRE。你正在分析一个日志模板的异常上下文。请严格按照以下 schema 输出合法 JSON，不要输出 markdown 围栏，不要额外文本。R\"output 必须严格满足：summary/likelyCause/suggestion 都是非空字符串；confidence 是 [0,1] 的数字。','分析这个日志模板的异常上下文：\n\n${inputSummary}\n\n请只返回严格的 JSON 对象，无任何前置/后续文本：\n{\"summary\":\"<20-80字，这个日志反映了什么>\",\"likelyCause\":\"<最可能的根因>\",\"suggestion\":\"<具体的处置建议>\",\"confidence\":0.0~1.0}','{\"type\": \"object\", \"required\": [\"summary\", \"likelyCause\", \"suggestion\", \"confidence\"], \"properties\": {\"summary\": {\"type\": \"string\", \"minLength\": 10}, \"confidence\": {\"type\": \"number\", \"maximum\": 1, \"minimum\": 0}, \"suggestion\": {\"type\": \"string\", \"minLength\": 5}, \"likelyCause\": {\"type\": \"string\", \"minLength\": 5}}, \"additionalProperties\": true}',1,1,'2026-09-28 12:00:28','2026-09-30 15:34:51');
INSERT IGNORE INTO `llm_prompt_template` (`id`, `scene_code`, `scene_name`, `system_prompt`, `user_prompt_tpl`, `output_schema`, `version`, `enabled`, `create_time`, `update_time`) VALUES (5,'similar_case_input','相似案例推断','你是日志查询助手，将自然语言转换为 Elasticsearch Query DSL。ES版本：7.x。可用索引模式：${indexPatterns}。字段映射：时间=${timeField} 内容=${messageField} 级别=${levelField} 服务=${serviceField}。级别取值：ERROR / WARN / INFO / DEBUG。严格输出JSON。','问题：${question}\n输出JSON：\n{\"index\":\"aiops-log-*\",\"query\":{},\"sort\":[{\"@timestamp\":\"desc\"}],\"size\":20,\"explain\":\"查询意图说明\",\"valid\":true}\n\n规则（必须遵守）：\n- 必须包含时间范围过滤，未指定时默认最近24小时\n- 只能使用上述已声明字段，不得编造字段名\n- 禁止使用 script 查询\n- 禁止任何写入或删除操作\n- 无法理解时 valid 设为 false','{\"type\": \"object\", \"required\": [\"matchedCaseId\", \"similarity\", \"reason\"], \"properties\": {\"reason\": {\"type\": \"string\"}, \"similarity\": {\"type\": \"number\", \"maximum\": 1, \"minimum\": 0}, \"matchedCaseId\": {\"type\": \"integer\"}}}',1,1,'2026-09-28 12:00:28','2026-09-30 15:34:51');
INSERT IGNORE INTO `llm_prompt_template` (`id`, `scene_code`, `scene_name`, `system_prompt`, `user_prompt_tpl`, `output_schema`, `version`, `enabled`, `create_time`, `update_time`) VALUES (6,'log_summary','日志摘要归纳','你是运维助手。基于给定的日志查询结果，用简洁中文回答用户的原始问题。','用户问题：${question}\n查询结果摘要：${resultSummary}\n\n用中文总结回答，指出关键信息。','{\"type\": \"object\", \"required\": [\"summary\", \"keyFindings\"], \"properties\": {\"summary\": {\"type\": \"string\", \"minLength\": 20}, \"confidence\": {\"type\": \"number\", \"maximum\": 1, \"minimum\": 0}, \"keyFindings\": {\"type\": \"array\", \"minItems\": 1}}}',1,1,'2026-09-28 12:00:28','2026-09-30 15:34:51');
INSERT IGNORE INTO `llm_prompt_template` (`id`, `scene_code`, `scene_name`, `system_prompt`, `user_prompt_tpl`, `output_schema`, `version`, `enabled`, `create_time`, `update_time`) VALUES (7,'report','故障报告','你是资深SRE。基于故障事件全部信息输出一份结构清晰的 Markdown 故障报告。','【故障事件】${incidentInfo}\n【告警列表】${alertList}\n【根因分析结论】${rootCause}\n【时间线】${timeline}\n\n输出 Markdown，目录固定为：\n## 一、故障概述 ## 二、影响范围 ## 三、时间线\n## 四、根因分析 ## 五、处置过程 ## 六、改进措施','{\"type\": \"object\", \"required\": [\"markdown\"], \"properties\": {\"markdown\": {\"type\": \"string\", \"minLength\": 100}, \"confidence\": {\"type\": \"number\", \"maximum\": 1, \"minimum\": 0}}, \"additionalProperties\": true}',1,1,'2026-09-28 12:00:28','2026-09-30 15:34:51');
INSERT IGNORE INTO `llm_prompt_template` (`id`, `scene_code`, `scene_name`, `system_prompt`, `user_prompt_tpl`, `output_schema`, `version`, `enabled`, `create_time`, `update_time`) VALUES (8,'nl2es_dsl','日志查询 DSL 生成','你是日志查询助手。将自然语言转换为 Elasticsearch Query DSL。ES版本：7.x。可用索引模式：aiops-log-*。字段映射：时间=@timestamp, 内容=message, 级别=level, 服务=service, traceId=traceId。级别取值：ERROR / WARN / INFO / DEBUG。严格输出 JSON，不要 markdown 围栏。','**严格警告：本平台只读，绝不提供 写入 / 删除 / 更新 / reindex / script / drop 等破坏性操作。** \n\n如果问题涉及以上行为，你必须绝票式回答（**不是 DSL**）：\n{\"valid\": false, \"blocked\": true, \"reason\": \"问题要求破坏性修改，本平台只读\"}\n\n否则你输出完整查询 DSL JSON（从 query 根开始）：\n问题：${question}\n可用时间窗：${timeHint}\n可用字段：${fieldInfo}\n可用服务名集合：${serviceList}\n\n输出必须为以下两种中的一种：\nA. 破坏性请求 → {\"valid\":false, \"blocked\":true, \"reason\":\"...\"}\nB. 合法查询请求 → {\"query\": ..., \"sort\": ..., \"size\": ...}\n\n规则：\n1. timeFilter 恒为 {range:{\"@timestamp\":{\"gte\":\"...\",\"lte\":\"...\"}}}，未明确 默认近 24 小时\n2. 只能用上述字段；禁止 script / painless / _update / _delete / _reindex / _bulk / _index / _create / drop\n3. size ≤ 100\n4. 服务名仅在 serviceList 中选择\n5. 不允许同时返回 DSL 和 valid=false —— 只选其一','{\"type\": \"object\", \"required\": [\"query\"], \"properties\": {\"aggs\": {\"type\": \"object\"}, \"size\": {\"type\": \"integer\", \"maximum\": 100, \"minimum\": 1}, \"sort\": {\"type\": \"array\"}, \"query\": {\"type\": \"object\"}, \"track_total_hits\": {\"type\": \"boolean\"}}, \"additionalProperties\": true}',4,1,'2026-10-01 23:57:09','2026-10-02 00:29:30');
INSERT IGNORE INTO `log_detect_rule` (`id`, `datasource_id`, `index_config_id`, `name`, `rule_type`, `params`, `level`, `enabled`, `create_time`, `update_time`, `deleted`) VALUES (1,1,1,'新模板告警','new_template','{\"threshold\": 1}','WARN',1,'2026-09-28 17:59:13','2026-09-28 17:59:13',0);
