INSERT IGNORE INTO `log_detect_rule` (`id`, `datasource_id`, `index_config_id`, `name`, `rule_type`, `params`, `level`, `enabled`, `create_time`, `update_time`, `deleted`) VALUES (3,1,1,'模板爆量','spike','{\"window_min\": 10, \"spike_ratio\": 3.0}','CRITICAL',1,'2026-09-28 17:59:13','2026-09-28 17:59:13',0);
