INSERT IGNORE INTO `kb_fault_case` (`id`, `title`, `symptom`, `root_cause`, `solution`, `tags`, `occurred_time`, `related_incident_id`, `source`, `embedding`, `create_time`, `deleted`, `embedding_status`) VALUES (1,'CPU 高负载告警预警异常集中','cpu.usage 突增 95%+，order-service / payment-service 有响应中并发瞬时请求加衡。','JVM 进程 GC 频繁，频繁 Full GC 导致请求处理中断，影响用户体验。','立即采用堆配置参数调优（增大年轻代+老年代比例），重启服务验证；长期：调优小池长效业务 bug 提交。','[\"cpu\", \"jvm\", \"gc\"]','2026-09-01 09:30:00',NULL,'manual','[0.03835025,0.05116705,-0.06598646,-0.020163922,0.008905419,0.058576755,-0.05251882,-0.01965075,-0.011502572,0.035947103,-0.0072219633,-0.00831089,-0.0068339547,0.010282223,0.033543956,0.03835025,0.016008478,-7.5528654E-4,0.013317451,0.02716059,-0.017159985,-0.031366102,0.00552912,-0.0376243,0.011515088,0.029188247,-0.0066274344,0.032667805,0.024732409,0.024657309,0.02242939,-0.0025470876,0.020777225,0.050791554,0.021728473,0.054921966,-0.007153123,0.015432722,0.0501407,0.023205407,0.041829813,-0.008949227,0.0058169975,-0.023593416,0.07905359,-0.0084423125,0.0070154425,-0.036347628,-0.036522858,0.031666495,-0.017660642,-0.012447561,0.054821838,-0.0022685977,0.0075974553,0.019275257,-0.008955485,-0.04405773,0.02364348,-0.037023515,-0.028562427,0.08335923,-0.021853635,0.015495304,0.018737052,0.007021701,0.04628565,-0.060429182,0.040953662,0.02903805,0.02993923,4.287845E-5,0.023280505,0.050290897,-0.009637629,0.023418186,0.02354335,-0.02194125,4.9518014E-4,-0.0027176235,-0.0047280705,-0.023831228,0.013993336,-0.008411021,0.004893913,-0.049389716,0.018061167,0.36928388,0.042130206,-0.009349751,-0.06783889,-0.034094676,0.0038613097,0.010876752,0.028036738,0.010163317,-0.03154133,0.020476831,7.7093206E-4,-0.018273946,0.022191579,-0.054621574,-0.03164146,-0.024369432,-0.011984454,-0.018461691,4.3298924E-4,-0.049014226,0.026634902,0.08015503,0.034345005,-0.003808115,0.010901785,0.039276466,0.016296353,-0.015945895,-0.014181082,-0.004020894,0.005432118,0.0044840006,-0.054821838,0.015244977,-0.025583524,0.013805591,-0.0041